root=Path(__file__).resolve().parents[1]
items=[]
skills={'A':'ANSWER_JUDGMENT','B':'ENTITY_ATTRIBUTE_MAPPING','C':'LISTENING_PROCESSING','D':'CTEST_RECONSTRUCTION','E':'VOCABULARY_DISCRIMINATION'}
