add('C','repair','강의의 공통 주제','listening',passage='Today we will compare two ways deserts conserve water. Some plants open their pores at night; others store water in thick stems. These are two different adaptations to dry conditions, rather than a history of one plant species.',prompt='What is the talk mainly about?',options={'A':'The history of one plant species','B':'Two plant adaptations that conserve water','C':'How deserts become oceans'},correctAnswer='B',evidence='two different adaptations to dry conditions',explanation='두 사례의 공통 주제는 수분을 보존하는 적응이다.',audioType='synthetic',audioLabel='Synthetic Practice Audio · 직접 제작 연습',recallMode='TOPIC / KEY POINTS / CONCLUSION',hint='도입과 두 사례를 하나로 묶는 주제를 고르세요.')
add('C','practice','연구실 출입 요청','listening',passage='Ari: I left my access card at home. Could you let me into the lab? Bo: Of course. I am standing beside the door now.',prompt='What does Ari want Bo to do?',options={'A':'Make a new access card','B':'Go to Ari’s home','C':'Open the lab door'},correctAnswer='C',evidence='Could you let me into the lab?',explanation='출입을 도와 달라는 요청이다. 카드 발급이나 귀가는 요청하지 않았다.',audioType='synthetic',audioLabel='Synthetic Practice Audio · 직접 제작 연습',recallMode='WHO / WHAT / WHERE / WHY / NEXT ACTION',hint='문장이 정보를 묻는지, 행동을 요청하는지 구분하세요.')
for title,prompt,p,options,key,evidence,tag in [
 ('도서 반납 순서','What should the student do next?','The student has already renewed the loan online. To collect the reserved book, she must first return the overdue volume at the desk. The librarian says: Please bring back the overdue volume now; then I can release your reservation.',{'A':'Renew the loan again','B':'Return the overdue volume','C':'Collect a book without visiting the desk'},'B','Please bring back the overdue volume now','ACTION_SEQUENCE'),
 ('관측 준비','What must happen before the camera is attached?','We have chosen the observation site and charged the batteries. Next, level the tripod. Only after the tripod is level should you attach the camera. Once it is attached, focus the lens.',{'A':'The tripod must be leveled.','B':'The lens must be focused.','C':'The site must be chosen again.'},'A','Only after the tripod is level should you attach the camera','ACTION_SEQUENCE'),
 ('발표 자료 검토','What is the woman asking for?','Woman: I have finished my slides, but the chart on page four may be confusing. Would you mind looking at that chart before I present it? Man: Sure. I will check it after lunch.',{'A':'A new presentation date','B':'Help checking a chart','C':'An invitation to lunch'},'B','Would you mind looking at that chart before I present it?','SPEECH_ACT'),
 ('의도와 장소 변경','What is the speaker doing?','The entrance is crowded, and our group cannot hear the instructions. Let’s move to the courtyard before we begin the tour. That way everyone can listen comfortably.',{'A':'Explaining why the tour has ended','B':'Asking about admission prices','C':'Suggesting a different place to gather'},'C','Let’s move to the courtyard before we begin the tour','SPEECH_ACT'),
 ('산호 연구','What is the main topic?','Today’s talk examines how scientists monitor reef health. Underwater photographs show changes in coral cover, temperature sensors track heat stress, and water samples reveal nutrient levels. These methods complement one another; none alone gives a complete picture.',{'A':'Several methods of monitoring reef health','B':'The history of underwater cameras','C':'A comparison of ticket prices for reef tours'},'A','how scientists monitor reef health','MAIN_IDEA'),
 ('철새의 이동 단서','What will the talk mainly compare?','Migrating birds can use the sun’s position during the day, star patterns at night, and Earth’s magnetic field when visual cues are weak. We will compare these navigation cues and discuss when each is useful. One species is an example, not the entire subject.',{'A':'The breeding schedule of one species','B':'Different navigation cues used by migrating birds','C':'Why all birds travel only at night'},'B','compare these navigation cues and discuss when each is useful','MAIN_IDEA')]:
 add('C','transfer',title,'listening',passage=p,prompt=prompt,options=options,correctAnswer=key,evidence=evidence,explanation='질문이 묻는 현재 행동·발화 기능·전체 주제를 해당 근거와 연결한다. 다른 단계나 한 사례를 정답으로 확대하지 않는다.',subSkillId=tag,audioType='synthetic',audioLabel='Synthetic Practice Audio · 직접 제작 연습',recallMode='TOPIC / KEY POINTS / CONCLUSION' if tag=='MAIN_IDEA' else 'WHO / WHAT / WHERE / WHY / NEXT ACTION',hint='핵심 대상과 현재 요청을 구분하고, 강의의 사례들은 공통 주제로 묶으세요.')
